START TRANSACTION;

ALTER TABLE `ny_user` ADD COLUMN IF NOT EXISTS `spend_week` DOUBLE(50,0) DEFAULT 0 AFTER `spend_day`;
ALTER TABLE `ny_user` ADD COLUMN IF NOT EXISTS `online_day` INT(11) UNSIGNED NOT NULL DEFAULT 0 AFTER `week_year`;
ALTER TABLE `ny_user` ADD COLUMN IF NOT EXISTS `online_last_ping` INT(11) UNSIGNED NOT NULL DEFAULT 0 AFTER `online_day`;
UPDATE `ny_user` SET `spend_week`=`spend_day` WHERE `spend_week`=0 AND `spend_day`>0;
UPDATE `ny_event` SET `display`=0 WHERE `type`='login_day';

INSERT INTO `ny_event` (`name`,`info`,`type`,`icon`,`milestone_type`,`comparison`,`prefix`,`suffix`,`expires_time`,`display`,`update_time`)
SELECT 'Tiêu Phí Ngày','Làm mới mỗi ngày.','spend_day',NULL,'money','>=','Tiêu','Xu',0,1,UNIX_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM `ny_event` WHERE `type`='spend_day');
UPDATE `ny_event` SET `name`='Tiêu Phí Ngày',`info`='Làm mới mỗi ngày.',`comparison`='>=',`prefix`='Tiêu',`suffix`='Xu',`expires_time`=0,`display`=1,`update_time`=UNIX_TIMESTAMP() WHERE `type`='spend_day';
SET @engagement_1=(SELECT `id` FROM `ny_event` WHERE `type`='spend_day' ORDER BY `id` LIMIT 1);
DELETE FROM `ny_event_milestone` WHERE `event_id`=@engagement_1 AND `need` NOT IN (20000,50000,100000,200000,500000,1000000,2000000,3000000,5000000,10000000);

