INSERT INTO `ny_event` (`name`,`info`,`type`,`icon`,`milestone_type`,`comparison`,`prefix`,`suffix`,`expires_time`,`display`,`update_time`)
SELECT 'Tiêu Phí Vĩnh Viễn','Không đặt lại; mỗi mốc chỉ nhận một lần.','spend_all',NULL,'money','>=','Tiêu','Xu',0,1,UNIX_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM `ny_event` WHERE `type`='spend_all');
UPDATE `ny_event` SET `name`='Tiêu Phí Vĩnh Viễn',`info`='Không đặt lại; mỗi mốc chỉ nhận một lần.',`comparison`='>=',`prefix`='Tiêu',`suffix`='Xu',`expires_time`=0,`display`=1,`update_time`=UNIX_TIMESTAMP() WHERE `type`='spend_all';
SET @engagement_4=(SELECT `id` FROM `ny_event` WHERE `type`='spend_all' ORDER BY `id` LIMIT 1);
